/* Token Radar dashboard: a dark terminal-style board. No network, no framework. */
:root {
  --bg: #0d1117;
  --panel: #161b22;
  --panel-2: #1c2128;
  --line: #2d333b;
  --text: #e6edf3;
  --muted: #8b949e;
  --accent: #3fb68b;
  --accent-dim: #1f6f54;
  --pos: #3fb68b;
  --neg: #f47067;
  --amber: #d29922;
  --mono: ui-monospace, "SF Mono", "Cascadia Code", Menlo, Consolas, monospace;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.5;
}
a { color: var(--accent); }
.skip {
  position: absolute;
  left: -999px;
  top: 0;
  background: var(--accent);
  color: #06110c;
  padding: 8px 12px;
  border-radius: 0 0 8px 0;
}
.skip:focus { left: 0; }
.shell { max-width: 1180px; margin: 0 auto; padding: 0 20px 48px; }
.top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 16px;
  flex-wrap: wrap;
  padding: 20px 0 12px;
  border-bottom: 1px solid var(--line);
}
.brand { display: flex; align-items: baseline; gap: 10px; }
.mark {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 4px rgba(63, 182, 139, 0.18);
}
.brand-name { font-weight: 700; font-size: 20px; letter-spacing: 0.2px; }
.top-meta { display: flex; gap: 16px; color: var(--muted); font-size: 13px; flex-wrap: wrap; }
.top-meta span { font-family: var(--mono); font-size: 12.5px; }
.lede { padding: 22px 0 8px; }
.lede h1 { font-size: 26px; line-height: 1.25; margin: 0 0 8px; }
.lede p { color: var(--muted); margin: 0 0 16px; max-width: 760px; }
.facts { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
.fact {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 12px 14px;
}
.fact span { display: block; color: var(--muted); font-size: 12.5px; margin-bottom: 4px; }
.fact b { font-family: var(--mono); font-size: 19px; font-weight: 600; }
.controls {
  display: flex;
  gap: 16px;
  align-items: flex-end;
  flex-wrap: wrap;
  padding: 16px 0;
}
.field { display: flex; flex-direction: column; gap: 6px; }
.field label, .field .sub { color: var(--muted); font-size: 12.5px; }
.field input, .field select {
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 9px 11px;
  font-size: 14px;
  font-family: var(--sans);
}
.field input { width: 280px; }
.field select { max-width: 220px; }
.field input:focus, .field select:focus { outline: 2px solid var(--accent-dim); border-color: var(--accent); }
.check { display: flex; align-items: center; gap: 8px; padding-bottom: 10px; color: var(--text); font-size: 14px; }
.check input { width: 16px; height: 16px; accent-color: var(--accent); }
.tabs { display: flex; gap: 0; }
.tabs button {
  background: var(--panel);
  color: var(--muted);
  border: 1px solid var(--line);
  padding: 9px 16px;
  font-size: 14px;
  cursor: pointer;
}
.tabs button:first-child { border-radius: 8px 0 0 8px; }
.tabs button:last-child { border-radius: 0 8px 8px 0; }
.tabs button[aria-pressed="true"] { background: var(--accent-dim); color: #fff; border-color: var(--accent-dim); }
.count { color: var(--muted); font-size: 13px; padding-bottom: 10px; }
.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 12px;
  margin: 8px 0 20px;
  overflow: hidden;
}
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
caption { text-align: left; padding: 14px 16px 8px; color: var(--muted); font-size: 13px; }
th, td { padding: 10px 14px; text-align: left; border-top: 1px solid var(--line); white-space: nowrap; }
thead th { border-top: 0; color: var(--muted); font-size: 12.5px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.4px; }
thead th button {
  background: none;
  border: 0;
  color: inherit;
  font: inherit;
  cursor: pointer;
  padding: 0;
  text-transform: inherit;
  letter-spacing: inherit;
}
thead th button:hover { color: var(--text); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--panel-2); }
tbody tr[data-selected="true"] { background: rgba(63, 182, 139, 0.1); }
.num { font-family: var(--mono); text-align: right; }
td.num, th.num { text-align: right; }
.name b { display: block; font-size: 14.5px; }
.name .sub, .sub { color: var(--muted); font-size: 12.5px; }
.pos { color: var(--pos); }
.neg { color: var(--neg); }
.implied { display: flex; align-items: center; gap: 10px; justify-content: flex-end; }
.bar { width: 74px; height: 6px; background: var(--line); border-radius: 3px; overflow: hidden; }
.bar i { display: block; height: 100%; background: var(--accent); }
.status {
  display: inline-block;
  font-size: 12px;
  font-family: var(--mono);
  padding: 2px 8px;
  border-radius: 20px;
  border: 1px solid var(--line);
  color: var(--muted);
}
.status.live { color: var(--amber); border-color: var(--amber); }
.empty { padding: 36px 24px; text-align: center; }
.empty h2 { margin: 0 0 6px; font-size: 18px; }
.empty p { color: var(--muted); margin: 0 0 16px; }
.button {
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 9px 16px;
  font-size: 14px;
  cursor: pointer;
}
.button.primary { background: var(--accent-dim); border-color: var(--accent-dim); color: #fff; }
.model { padding: 20px 22px; }
.model h2 { margin: 0 0 6px; font-size: 18px; }
.model p { color: var(--muted); margin: 0 0 12px; }
.formula {
  font-family: var(--mono);
  font-size: 13px;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px 14px;
  overflow-x: auto;
  margin: 0 0 14px;
  line-height: 1.7;
}
.formula b { color: var(--accent); }
.comp-wrap { overflow-x: auto; }
.comp-wrap table { font-size: 13.5px; }
.comp-wrap td, .comp-wrap th { padding: 7px 12px; }
.note { font-size: 12.5px; color: var(--muted); margin: 10px 0 0; }
.detail {
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 0;
  width: min(680px, 94vw);
  max-height: 88vh;
  overflow-y: auto;
}
.detail::backdrop { background: rgba(0, 0, 0, 0.6); }
.detail-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 22px 0;
}
.detail-head h2 { margin: 4px 0 4px; font-size: 22px; }
.detail-head .sub { margin: 0; }
.close {
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px 14px;
  height: fit-content;
  cursor: pointer;
  font-size: 14px;
}
.detail-section { padding: 18px 22px 22px; }
.detail-section h3 { margin: 0 0 12px; font-size: 15px; }
.equation { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 20px; }
.equation > div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px dashed var(--line);
  padding-bottom: 8px;
}
.equation span { color: var(--muted); font-size: 13px; }
.equation b { font-family: var(--mono); font-weight: 600; }
.steps { margin: 0; padding-left: 22px; }
.steps li { margin-bottom: 12px; }
.steps li b { display: block; font-weight: 600; }
.steps .cost { color: var(--muted); font-size: 13px; }
@media (max-width: 760px) {
  .facts { grid-template-columns: repeat(2, 1fr); }
  .field input { width: 100%; }
  .equation { grid-template-columns: 1fr; }
  .bar { display: none; }
}
